import React from "react";
import { FaBolt, FaUserGraduate, FaLeaf, FaBrain } from "react-icons/fa";

const Projects = () => {
  return (
    <section className="network-page">

      {/* HEADER */}
      <div className="header">
        <h1>Project <span>Neural Map</span></h1>
        <p>Connected system of my development work</p>
      </div>

      {/* NETWORK */}
      <div className="network">

        {/* CENTER NODE */}
        <div className="node center">
          <FaBrain />
          <h3>Core Logic</h3>
          <p>My Development System</p>
        </div>

        {/* ENERGY PULSE */}
        <div className="node p1">
          <FaBolt />
          <h3>EnergyPulse</h3>
          <p>AI-based smart home dashboard with real-time biometric & energy monitoring.</p>
          <span>React.js • UI Dashboard</span>
        </div>

        {/* STUDENT PORTAL */}
        <div className="node p2">
          <FaUserGraduate />
          <h3>Student Portal</h3>
          <p>Full-stack system for managing student records and academic operations.</p>
          <span>Spring Boot • MySQL • Java</span>
        </div>

        {/* COGNI FLOW */}
        <div className="node p3 highlight">
          <FaBrain />
          <h3>Cogni Flow</h3>
          <p>Interactive thinking flow system that visualizes structured cognitive problem solving.</p>
          <span>HTML • CSS • JavaScript</span>
        </div>

        {/* FARM2FORK */}
        <div className="node p4">
          <FaLeaf />
          <h3>Farm2Fork</h3>
          <p>Frontend platform connecting farmers and consumers through smooth UI experience.</p>
          <span>HTML • CSS • JavaScript</span>
        </div>

        {/* CONNECTION LINES */}
        <div className="line l1"></div>
        <div className="line l2"></div>
        <div className="line l3"></div>
        <div className="line l4"></div>

      </div>

      {/* ACHIEVEMENTS (SEPARATE SECTION) */}
      <div className="achievements">

        <h2>Achievements</h2>

        <div className="ach-grid">

          <div className="ach-card">
            <h3>SIH 2025</h3>
            <p>Semi-finalist in Smart India Hackathon</p>
          </div>

          <div className="ach-card">
            <h3>Best Project Award</h3>
            <p>Li-Fi innovation at international conference</p>
          </div>

          <div className="ach-card">
            <h3>Code Crunch</h3>
            <p>Organized DSA-based coding event</p>
          </div>

          <div className="ach-card">
            <h3>Event Coordinator</h3>
            <p>Managed technical + non-technical events</p>
          </div>

        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .network-page {
          min-height: 100vh;
          padding: 60px 10%;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
          font-family: "Poppins", sans-serif;
        }

        /* HEADER */
        .header {
          text-align: center;
          margin-bottom: 50px;
        }

        .header h1 {
          font-size: 40px;
        }

        .header span {
          color: #38BDF8;
        }

        .header p {
          color: #94a3b8;
        }

        /* NETWORK */
        .network {
          position: relative;
          height: 550px;
        }

        /* CENTER */
        .center {
          position: absolute;
          top: 50%;
          left: 50%;
          transform: translate(-50%, -50%);
          border: 1px solid #38BDF8;
          background: rgba(56,189,248,0.1);
          box-shadow: 0 0 25px rgba(56,189,248,0.3);
        }

        /* NODES */
        .node {
          position: absolute;
          width: 260px;
          padding: 14px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .node:hover {
          transform: scale(1.05);
          box-shadow: 0 0 20px rgba(56,189,248,0.3);
        }

        .node h3 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .node p {
          font-size: 13px;
          color: #cbd5e1;
          line-height: 1.5;
        }

        .node span {
          font-size: 12px;
          color: #94a3b8;
        }

        .highlight {
          border: 1px solid #38BDF8;
          box-shadow: 0 0 25px rgba(56,189,248,0.2);
        }

        /* POSITIONS */
        .p1 { top: 10%; left: 5%; }
        .p2 { top: 10%; right: 5%; }
        .p3 { bottom: 10%; left: 5%; }
        .p4 { bottom: 10%; right: 5%; }

        /* LINES */
        .line {
          position: absolute;
          background: rgba(56,189,248,0.15);
        }

        .l1 { width: 2px; height: 300px; top: 20%; left: 50%; }
        .l2 { width: 300px; height: 2px; top: 50%; left: 10%; }
        .l3 { width: 300px; height: 2px; top: 50%; right: 10%; }
        .l4 { width: 2px; height: 300px; bottom: 20%; left: 50%; }

        /* ACHIEVEMENTS */
        .achievements {
          margin-top: 80px;
        }

        .achievements h2 {
          text-align: center;
          color: #38BDF8;
          margin-bottom: 30px;
        }

        .ach-grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 20px;
        }

        .ach-card {
          padding: 16px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.2);
          border-radius: 14px;
          text-align: center;
        }

        .ach-card h3 {
          color: #38BDF8;
          margin-bottom: 6px;
        }

        .ach-card p {
          color: #cbd5e1;
          font-size: 13px;
        }

        @media (max-width: 900px) {
          .network {
            height: auto;
          }

          .node {
            position: relative;
            width: 100%;
            margin-bottom: 20px;
          }

          .ach-grid {
            grid-template-columns: 1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Projects;
